import{z as A,x as d,o as E,c as B,q as t,j as s,D as e,d as i,s as l,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"覆盖引导 fuzzing","description":"","frontmatter":{"title":"覆盖引导 fuzzing","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/coverage-guided-fuzzing.md","filePath":"cs/coverage-guided-fuzzing.md","lastUpdated":1791413859000}'),p={name:"cs/coverage-guided-fuzzing.md"};function u(z,a,f,c,m,g){const n=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=t('<h1 id="覆盖引导-fuzzing" tabindex="-1">覆盖引导 fuzzing <a class="header-anchor" href="#覆盖引导-fuzzing" aria-label="Permalink to &quot;覆盖引导 fuzzing&quot;">​</a></h1><div class="epigraph"><p>随机输入若能看见「覆盖了新边」，就能把变异压向未走过的分支。AFL 一类工具把程序当仪器，而不是当证明器：找到的是崩溃，不是无洞。</p><footer>—— Zalewski, American Fuzzy Lop；libFuzzer；Manès et al., The Art, Science, and Engineering of Fuzzing, TSE</footer></div><p>上一课<a href="/cs/memory-safe-languages">内存安全语言</a>承认遗留 C 仍在。缺口是<strong>如何便宜地找崩溃</strong>：覆盖引导 fuzz。不把符号执行提前讲完。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手工测试到不了深层分支。插桩记录边覆盖，语料库保留能长覆盖的输入，变异（位翻转、字典）围着它们转。缺口是：无崩溃不等于安全；覆盖不是功能正确。</p><h3 id="要有预言" tabindex="-1">要有预言 <a class="header-anchor" href="#要有预言" aria-label="Permalink to &quot;要有预言&quot;">​</a></h3><p>只看信号量崩溃会漏逻辑洞。Sanitizer 下一课把更多未定义变成崩溃。</p><p><span class="marginnote">AFL；libFuzzer。本课不提供对第三方产品的 fuzz 作战计划。种子语料来自合法文件。</span></p><p><span class="marginnote">插桩可以翻译成「给程序装计步器」：编译时在每个分支处塞一小段代码，把「这条边走过没有」记进共享位图。fuzzer 一看位图有新格点亮，就知道这个输入把它带到了没去过的分支——全程不需要懂程序的业务逻辑。</span></p><p><span class="marginnote">直觉类比：盲变异像往保险箱上瞎拧转盘，覆盖反馈像每拧对一格就有「咔」的一声——你知道自己更近了，于是顺着这个方向继续拧。语料库就是「到目前为止拧对最多格的那几个转法」的存档。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：语料→变异→执行→覆盖反馈→保留。指出结构感知（协议、语法）提高密度。对照符号执行：精确路径条件，更贵。</p>',13)),(E(),s(o,null,{default:e(()=>[l(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CORP%5B%22%E8%AF%AD%E6%96%99%22%5D%20--%3E%20MUT%5B%22%E5%8F%98%E5%BC%82%22%5D%0A%20%20MUT%20--%3E%20RUN%5B%22%E6%8F%92%E6%A1%A9%E6%89%A7%E8%A1%8C%22%5D%0A%20%20RUN%20--%3E%20COV%5B%22%E6%96%B0%E8%A6%86%E7%9B%96%3F%22%5D%0A%20%20COV%20--%3E%20CORP%0A%20%20RUN%20--%3E%20CRASH%5B%22%E5%B4%A9%E6%BA%83%E5%85%A5%E6%A1%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[i("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"发现课把「利用课的洞」变成可回归的测试输入。下一课 KLEE：用约束求解补随机走不到的分支。",-1)),(E(),s(o,null,{default:e(()=>[l(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOAL%5B%22%E7%9B%AE%E6%A0%87%E6%98%AF%E8%B5%B0%E5%88%B0%E6%B7%B1%E5%B1%82%E5%88%86%E6%94%AF%22%5D%20--%3E%20BF%5B%22%E7%9B%B2%E5%8F%98%E5%BC%82%22%5D%0A%20%20GOAL%20--%3E%20CG%5B%22%E8%A6%86%E7%9B%96%E5%BC%95%E5%AF%BC%22%5D%0A%20%20GOAL%20--%3E%20SE%5B%22%E7%AC%A6%E5%8F%B7%E6%89%A7%E8%A1%8C%22%5D%0A%20%20BF%20--%3E%20BFI%5B%22%E7%9C%8B%E4%B8%8D%E5%88%B0%E8%BF%9C%E8%BF%91%20%E5%91%BD%E4%B8%AD%E9%9D%A0%E8%BF%90%E6%B0%94%20%E6%88%90%E6%9C%AC%E6%9C%80%E4%BD%8E%22%5D%0A%20%20CG%20--%3E%20CGI%5B%22%E6%AF%8F%E6%AD%A5%E7%9C%8B%E8%A6%86%E7%9B%96%20%E5%8F%98%E5%BC%82%E6%9C%89%E6%96%B9%E5%90%91%20%E6%88%90%E6%9C%AC%E4%B8%AD%E7%AD%89%22%5D%0A%20%20SE%20--%3E%20SEI%5B%22%E8%A7%A3%E8%B7%AF%E5%BE%84%E7%BA%A6%E6%9D%9F%20%E4%B8%80%E6%AC%A1%E5%88%B0%E4%BD%8D%20%E6%B1%82%E8%A7%A3%E5%BC%80%E9%94%80%E5%A4%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">这张图回答「为什么偏偏选中覆盖引导」：三种技术是成本与精度的阶梯。盲变异便宜但瞎；符号执行精确但求解贵、路径爆炸；覆盖引导用极低的插桩代价换来方向感，是工程上的甜点位。</span></p><p><span class="marginnote">常见误区：以为「fuzz 跑了一夜没崩＝没有漏洞」。没有预言的 fuzz 看不见逻辑错误——把密码比较写成恒真它也不崩；覆盖率高也不等于功能正确。Sanitizer（下一课）的用处是把越界、未定义行为等更多坏事变成可见崩溃。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写武器化崩溃。符号执行下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>遗留 C 要用自动发现。</li><li>覆盖反馈引导变异；崩溃是信号。</li><li>无崩溃 ≠ 无洞。</li><li>下一课符号执行 KLEE。</li><li>出处：Zalewski, AFL；libFuzzer；Manès et al., TSE。</li></ul>',6))])}const D=A(p,[["render",u]]);export{h as __pageData,D as default};
